package com.sertumrosarum.domain.prayer

internal val joyfulLuminousStudies: Map<Pair<MysterySet, Int>, MysteryStudy> = mapOf(
    (MysterySet.JOYFUL to 0) to MysteryStudy(
        scriptureTitle = "O anjo Gabriel é enviado a Nazaré",
        scriptureReading = "No sexto mês da gestação de Isabel, o anjo Gabriel é enviado por Deus a uma aldeia da Galileia chamada Nazaré, a uma jovem desposada com José, da casa de Davi. O anjo a saúda: «Alegra-te, cheia de graça, o Senhor está contigo». Perturbada com a saudação, Maria pergunta como isso se fará, pois não conhece homem. Gabriel anuncia que o Espírito Santo virá sobre ela e que o poder do Altíssimo a cobrirá com sua sombra; o Menino será chamado Filho de Deus. Maria responde em liberdade: «Eis aqui a serva do Senhor; faça-se em mim segundo a tua palavra».",
        historicalContext = "Nazaré era uma pequena aldeia agrícola da Galileia, nunca mencionada no Antigo Testamento — um lugar improvável para o início da salvação. A saudação «Alegra-te» (chaire) ecoa os oráculos proféticos à Filha de Sião (Sf 3,14; Zc 9,9), anunciando que Deus finalmente vem habitar no meio do seu povo. A expressão «cobrir com a sombra» remete diretamente à nuvem da Glória de Deus (Shekinah) que envolvia a Arca da Aliança no deserto (Ex 40,35). Maria é apresentada como a nova morada viva do Altíssimo, onde o sim livre de uma criatura desata o nó da desobediência de Eva.",
        theologicalDepth = "A Encarnação é o ponto de virada da história: o Filho eterno assume verdadeira carne humana sem deixar de ser Deus. Maria não é instrumento passivo; Deus espera o seu consentimento livre. Sua resposta de fé — o «Fiat» — revela que a graça não anula a liberdade humana, mas a eleva à sua máxima plenitude. Desde este instante, Jesus é verdadeiro Deus e verdadeiro homem, e Maria é, com toda propriedade, Mãe de Deus (Theotókos).",
        catechismRefs = "CIC 484–494; 508–511; 2617",
        saintsVoices = listOf(
            SaintVoice(
                "São Bernardo de Claraval",
                "Homilias sobre a Virgem Mãe (Missus est)",
                "Contempla toda a criação em silêncio esperando a resposta de Maria: Adão exilado, os patriarcas e os profetas aguardam uma palavra breve que abrirá as portas da salvação. O sim humilde de uma jovem de Nazaré torna-se o sim de toda a humanidade à misericórdia de Deus."
            ),
            SaintVoice(
                "São João Paulo II",
                "Rosarium Virginis Mariae, 14–20",
                "O Rosário começa aqui porque a fé cristã nasce da escuta. Maria guarda a Palavra antes no coração do que no ventre; aprender a contemplar com ela é deixar que o Evangelho encontre espaço concreto no silêncio do nosso cotidiano."
            ),
        ),
        symbols = listOf(
            MysterySymbol("«Cheia de graça» (Kecharitōménē)", "Um nome novo dado por Deus: Maria foi transformada pela graça desde a origem para acolher o Redentor."),
            MysterySymbol("A sombra do Altíssimo", "A mesma nuvem luminosa que cobria o Tabernáculo no Êxodo agora envolve Maria, nova Arca da Aliança."),
            MysterySymbol("O «Faça-se» (Fiat)", "Não é resignação passiva, mas disponibilidade corajosa de quem confia na fidelidade de Deus."),
        ),
        reflectionQuestions = listOf(
            "Que lugar «pequeno» ou discreto da minha vida hoje Deus deseja visitar, mesmo quando eu esperava algo grandioso?",
            "Quando uma palavra ou circunstância me perturba, eu paro para discernir com calma como Maria, ou reajo no impulso do medo?",
            "Qual «faça-se» concreto o Senhor está me convidando a pronunciar hoje com liberdade?"
        ),
        closingPrayer = "Senhor, que no silêncio de Nazaré entrastes em nossa história, ensinai-me a escutar Vossa Palavra com a disponibilidade humilde de Maria. Amém."
    ),
    (MysterySet.JOYFUL to 1) to MysteryStudy(
        scriptureTitle = "Maria põe-se a caminho às pressas para a Judeia",
        scriptureReading = "Logo após o anúncio do anjo, Maria se levanta e parte apressadamente para a região montanhosa da Judeia, entrando na casa de Zacarias e saudando Isabel. Assim que Isabel ouve a saudação, a criança estremece de alegria em seu ventre e ela fica cheia do Espírito Santo. Em alta voz proclama Maria bendita entre as mulheres e bendito o fruto do seu ventre, maravilhada porque a mãe do seu Senhor veio visitá-la. Maria então entoa o Magnificat, celebrando o Deus que olha para a pequenez dos humildes e cumpre suas promessas.",
        historicalContext = "A viagem de Nazaré até a região montanhosa de Judá (tradicionalmente identificada com Ain Karim, perto de Jerusalém) ultrapassava 120 quilômetros por caminhos acidentados — uma jornada de vários dias para uma jovem recém-grávida. Lucas estrutura a cena em paralelo intencional com o traslado da Arca da Aliança por Davi (2Sm 6): ambos viajam à região montanhosa de Judá; Davi pergunta «Como virá a mim a Arca do Senhor?» e Isabel exclama «Donde me vem que a mãe do meu Senhor venha a mim?»; Davi dança de alegria diante da Arca, João salta no ventre; a Arca permanece três meses na casa de Obed-Edom, e Maria fica cerca de três meses com Isabel.",
        theologicalDepth = "Quem acolhe verdadeiramente Cristo não pode fechar-se num intimismo estéril: a graça gera pressa de servir. Maria torna-se a primeira missionária do Evangelho, levando Jesus silenciosamente no ventre antes mesmo de qualquer discurso. No encontro de duas mães — uma jovem, outra idosa — o Espírito Santo desperta a alegria messiânica e o louvor do Magnificat, que une mística e justiça social: Deus derruba a soberba e sustenta os famintos.",
        catechismRefs = "CIC 524; 717; 2619; 2676",
        saintsVoices = listOf(
            SaintVoice(
                "Santo Ambrósio de Milão",
                "Comentário ao Evangelho de São Lucas",
                "Maria foi às pressas não por incredulidade ou dúvida sobre o sinal, mas pela alegria do desejo e pela prontidão do serviço: a graça do Espírito Santo não conhece lentidão quando a caridade chama."
            ),
            SaintVoice(
                "São Luís Maria Grignion de Montfort",
                "Tratado da Verdadeira Devoção",
                "Onde Maria entra, Cristo já age em segredo. Como João Batista foi santificado ao som da saudação de Maria, a presença materna dela desperta em nós o reconhecimento alegre do Senhor."
            ),
        ),
        symbols = listOf(
            MysterySymbol("As montanhas da Judeia", "O amor verdadeiro atravessa cansaço, distância e relevo difícil para chegar até quem precisa."),
            MysterySymbol("O estremecer de João", "A alegria profunda que nasce quando uma vida reconhece, pelo Espírito, a proximidade de Jesus."),
            MysterySymbol("O Magnificat", "O cântico dos pobres de Deus: louvor que reconhece a grandeza do Senhor sem apagar a própria pequenez."),
        ),
        reflectionQuestions = listOf(
