        closingPrayer = "Jesus, levado por Maria pelos caminhos da montanha, libertai-me do egoísmo e fazei de meus encontros lugares de serviço e alegria. Amém."
    ),
    (MysterySet.JOYFUL to 2) to MysteryStudy(
        scriptureTitle = "O nascimento de Jesus em Belém",
        scriptureReading = "Por causa de um recenseamento decretado por César Augusto, José sobe de Nazaré a Belém, cidade de Davi, acompanhado de Maria, sua esposa, que esperava um filho. Enquanto estavam ali, completaram-se os dias do parto, e ela deu à luz seu filho primogênito, envolveu-o em faixas e o deitou numa manjedoura, pois não havia lugar para eles na hospedaria. Nos campos próximos, anjos anunciam a pastores em vigília a grande alegria: nasceu o Salvador, Cristo Senhor. Os pastores vão depressa, encontram Maria, José e o Menino, e Maria guarda tudo no coração.",
        historicalContext = "Belém significa literalmente «Casa do Pão» (Beit Lechem) — anúncio silencioso d'Aquele que dirá «Eu sou o pão vivo descido do céu». A manjedoura era o cocho de pedra ou madeira onde se punha alimento para os animais, frequentemente numa gruta ou pavimento térreo de uma casa camponesa. Os pastores ocupavam um lugar marginal na sociedade judaica da época e muitas vezes não podiam cumprir todas as regras de pureza ritual; escolhê-los como primeiros convidados mostra que o Evangelho começa pelos pequenos e descartados. O contraste entre César Augusto, que se proclamava «salvador e portador da paz» por decreto imperial, e o Menino envolvido em faixas revela o estilo desconcertante de Deus.",
        theologicalDepth = "O Natal revela o mistério da kénosis — o rebaixamento amoroso de Deus que assume a condição humana na total fragilidade de um recém-nascido. A pobreza da manjedoura não romantiza a miséria, mas declara que a dignidade humana não se mede por poder, status ou riqueza. Ao contemplar o presépio, aprendemos a admirável troca (admirabile commercium): o Filho de Deus se faz homem para que o ser humano possa participar da vida divina.",
        catechismRefs = "CIC 456–460; 525–526; 563",
        saintsVoices = listOf(
            SaintVoice(
                "São Leão Magno",
                "Sermões sobre o Natal do Senhor",
                "Reconhece, ó cristão, a tua dignidade! Nenhuma tristeza tem lugar onde nasce a Vida. A humildade de Belém nos ensina que a grandeza diante de Deus consiste na simplicidade de um coração acolhedor."
            ),
            SaintVoice(
                "São Francisco de Assis",
                "A memória viva do presépio em Greccio",
                "Quis contemplar com os próprios olhos a pobreza em que o Menino quis nascer, deitado no feno entre o boi e o jumento, para que o amor de Deus deixasse de ser uma ideia distante e aquecesse o coração concreto."
            ),
        ),
        symbols = listOf(
            MysterySymbol("Belém, «Casa do Pão»", "O Menino reclinado no cocho de alimento prefigura a Eucaristia, onde Cristo se faz pão entregue por nós."),
            MysterySymbol("As faixas do recém-nascido", "Sinal de cuidado materno e também presságio das faixas de linho do sepulcro na Páscoa."),
            MysterySymbol("A vigília dos pastores", "Só quem permanece acordado e sem pretensões consegue ouvir o canto discreto dos anjos na noite."),
        ),
        reflectionQuestions = listOf(
            "Que excessos, pressas ou apegos ocupam hoje a «hospedaria» do meu coração, deixando pouco espaço para Cristo?",
            "Como trato pessoas que ocupam lugares discretos ou marginalizados no meu cotidiano?",
            "Sei guardar no coração, como Maria, aquilo que ainda não compreendo por inteiro?"
