        closingPrayer = "Menino de Belém, que escolhestes a simplicidade de uma manjedoura, ensinai-me o desprendimento e a alegria de acolher-Vos nos pequenos. Amém."
    ),
    (MysterySet.JOYFUL to 3) to MysteryStudy(
        scriptureTitle = "A apresentação de Jesus no Templo",
        scriptureReading = "Cumpridos os dias da purificação segundo a Lei de Moisés, Maria e José levam o Menino a Jerusalém para apresentá-lo ao Senhor, oferecendo um par de rolas ou dois pombinhos, a oferta dos pobres. No Templo estava Simeão, homem justo e piedoso que esperava a consolação de Israel. Movido pelo Espírito, toma Jesus nos braços, bendiz a Deus e proclama que seus olhos viram a salvação — luz para as nações e glória de Israel. Depois anuncia a Maria que o Menino será sinal de contradição e que uma espada atravessará sua alma. Também a profetisa Ana louva a Deus e fala do Menino a todos.",
        historicalContext = "Pela Lei do Êxodo (Ex 13,2), todo primogênito pertencia ao Senhor e devia ser resgatado, enquanto Levítico 12 previa a oferta de um cordeiro ou — para famílias sem recursos — duas rolas ou pombinhos. A oferta de José e Maria atesta sua condição humilde. Mais profundamente, realiza-se a profecia de Malaquias (Ml 3,1): «Logo entrará no seu templo o Senhor que buscais». O verdadeiro Cordeiro não é comprado no pátio do Templo; entra nos braços de sua mãe. Simeão e Ana representam o «resto fiel» de Israel, pessoas idosas cuja longa espera em oração e jejum afinou o olhar para reconhecer Deus na fragilidade de um bebê.",
        theologicalDepth = "Este mistério une alegria e sombra da cruz: pela primeira vez, a Paixão é anunciada diretamente a Maria através da espada de Simeão. A obediência de Cristo à Lei não é legalismo frio, mas entrega filial de toda a vida ao Pai. Maria aprende desde cedo que o amor materno não retém o Filho para si, mas o entrega à missão que salvará todos os povos. Também a velhice aparece aqui com imensa dignidade espiritual: quem persevera na esperança torna-se testemunha luminosa.",
        catechismRefs = "CIC 527–529; 534; 583",
        saintsVoices = listOf(
            SaintVoice(
                "São João Paulo II",
                "Redemptoris Mater, 16",
                "A profecia de Simeão é como uma segunda Anunciação: revela a Maria que ela viverá sua obediência de fé no sofrimento junto ao Salvador, e que sua maternidade se tornará companheira da Cruz."
            ),
            SaintVoice(
                "Santo Tomás de Aquino",
                "Suma Teológica, III, q. 37",
                "Cristo quis submeter-se às prescrições da Lei para manifestar sua humildade verdadeira, dar exemplo de obediência e cumprir por dentro a Antiga Aliança antes de inaugurar a Nova."
            ),
        ),
        symbols = listOf(
            MysterySymbol("As duas rolas", "A oferta prevista para os pobres na Lei de Moisés revela que a Sagrada Família viveu na sobriedade real."),
            MysterySymbol("Luz para as nações", "Daí nasce a festa litúrgica da Candelária: Cristo é a chama que ilumina a noite de todos os povos."),
            MysterySymbol("A espada na alma de Maria", "O amor autêntico nunca nos blinda da dor; ele nos torna capazes de permanecer fiéis atravessando-a."),
        ),
        reflectionQuestions = listOf(
            "Eu ofereço a Deus minha vida inteira — inclusive o que me é mais querido — ou tento negociar com Ele o que quero reter?",
            "Tenho cultivado a paciência esperançosa de Simeão e Ana quando as respostas de Deus demoram?",
            "Como valorizo e escuto a sabedoria dos idosos na minha família e na Igreja?"
