    (MysterySet.LUMINOUS to 0) to MysteryStudy(
        scriptureTitle = "O Batismo de Jesus no rio Jordão",
        scriptureReading = "Jesus vem da Galileia ao rio Jordão para ser batizado por João. João tenta impedi-lo, reconhecendo que ele mesmo precisa ser batizado por Jesus, mas o Senhor responde que convém cumprir toda a justiça. Assim que Jesus sai da água, os céus se abrem, o Espírito de Deus desce sobre ele como uma pomba e uma voz do céu declara: «Este é o meu Filho amado, em quem me comprazo».",
        historicalContext = "O rio Jordão, no ponto mais baixo da superfície terrestre perto de Jericó, era o lugar onde Israel entrara na Terra Prometida séculos antes (Js 3). O batismo de João era um rito de arrependimento para pecadores. Jesus, o Inocente, desce voluntariamente à fila dos pecadores para assumir nossa condição ferida. A abertura dos céus cumpre a súplica dramática de Isaías («Ah, se rasgasses os céus e descesses!», Is 63,19), e a voz do Pai funde dois textos messiânicos: o Rei entronizado do Salmo 2,7 («Tu és meu Filho») e o Servo Sofredor de Isaías 42,1 («em quem me comprazo»).",
        theologicalDepth = "O Batismo no Jordão é uma teofania trinitária plena: o Pai fala, o Filho desce às águas, o Espírito repousa sobre Ele. Jesus não precisava de purificação; ao entrar na água, Ele a santifica e antecipa o «batismo» da sua morte e ressurreição. Para cada cristão, o próprio Batismo nos insere nesta mesma voz do Pai: antes de qualquer mérito ou desempenho, somos chamados filhos e filhas amados.",
        catechismRefs = "CIC 535–537; 1223–1225; 1265–1270",
        saintsVoices = listOf(
            SaintVoice(
                "São João Paulo II",
                "Rosarium Virginis Mariae, 21",
                "Mistério de luz é antes de tudo o Batismo no Jordão: enquanto Cristo desce às águas como inocente que se faz pecado por nós, o céu se abre e a voz do Pai o proclama Filho amado, enquanto o Espírito o investe na missão."
            ),
            SaintVoice(
                "Santo Inácio de Antioquia",
                "Carta aos Efésios, 18",
