        symbols = listOf(
            MysterySymbol("Descer às águas", "Solidariedade radical de Deus: Jesus não nos salva de longe, mas entra na nossa fragilidade."),
            MysterySymbol("Os céus rasgados", "A distância entre o céu e a terra foi rompida para sempre em Cristo."),
            MysterySymbol("A pomba sobre as águas", "Evoca o Espírito pairando sobre as águas na Criação (Gn 1,2) e a pomba de Noé: começa uma nova criação."),
        ),
        reflectionQuestions = listOf(
            "Eu acredito de verdade que sou filho ou filha amado de Deus antes de provar qualquer resultado?",
            "Em que área da minha vida preciso abrir-me hoje à ação serena e corajosa do Espírito Santo?",
            "Como tenho vivido na prática as promessas do meu próprio Batismo?"
